# apply_workflow.py — installs the weekly predict-next-race CLI.
# After install, run:  python -m src.cli.predict_next
import base64, pathlib

FILES = {
    'src/cli/predict_next.py': '',
}


def main():
    for target, b64 in FILES.items():
        p = pathlib.Path(target)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(b64))
        print(f"wrote {target}")
    print("\nRun with:  python -m src.cli.predict_next")
    print("Override race:  python -m src.cli.predict_next --race-id 2026-5625")
    print("Skip data refresh:  python -m src.cli.predict_next --no-refresh")

if __name__ == "__main__":
    main()
